<script setup lang="ts">
import { onMounted, ref } from 'vue'; import Notice from '@/components/Notice.vue'; import { useDashboardStore } from '@/stores/dashboard'
const store = useDashboardStore(); const notice = ref(''); const error = ref(''); const busy = ref(false)
async function act(task: () => Promise<unknown>, success: string) { busy.value = true; error.value = ''; notice.value = ''; try { await task(); notice.value = success } catch (reason) { error.value = reason instanceof Error ? reason.message : '操作失败' } finally { busy.value = false } }
onMounted(() => store.loadPublic())
</script>
<template><div class="page"><div class="page-heading"><div><span class="eyebrow">控制台</span><h1>状态与设备</h1></div></div><Notice :message="notice" type="success"/><Notice :message="error || store.error" type="error"/><section class="section"><div class="section-title"><h2>状态预设</h2></div><div class="button-grid"><button v-for="preset in store.presets" :key="preset.id" :class="{ selected: store.snapshot?.status === preset.id }" :disabled="busy" @click="act(() => store.setStatus(preset.id), `已切换为${preset.name}`)"><strong>{{ preset.name }}</strong><small>{{ preset.desc }}</small></button></div></section><section class="section"><div class="section-title"><h2>隐私模式</h2><button class="switch" :class="{ on: store.snapshot?.private }" :disabled="busy" @click="act(() => store.setPrivacy(!store.snapshot?.private), '隐私模式已更新')"><span/>{{ store.snapshot?.private ? '已开启' : '已关闭' }}</button></div><p class="muted">开启后，公开状态和实时推送不会暴露设备列表。</p></section><section class="section"><div class="section-title"><h2>设备管理</h2><button class="danger ghost" :disabled="busy || !store.snapshot?.devices.length" @click="act(store.clearDevices, '设备已清空')">清空全部</button></div><p v-if="!store.snapshot?.devices.length" class="empty">暂无可管理设备。</p><div v-else class="list"><article v-for="device in store.snapshot.devices" :key="device.id"><div><strong>{{ device.name }}</strong><p>{{ device.status || '暂无状态' }} · {{ device.id }}</p></div><button class="danger ghost" :disabled="busy" @click="act(() => store.removeDevice(device.id), '设备已移除')">移除</button></article></div></section></div></template>
